104	/// Quotes an option literally.
105	pub fn quote_option<T: ToTokens>(option: &Option<T>) -> TokenStream {
106	    if let Some(value) = option {
107	        quote! { Some(#value) }
108	    } else {
109	        quote! { None }
110	    }
111	}
